mapper.select:
SELECT p.id, p.product_code, p.name, p.subtitle, p.cover_url, p.detail_content, p.price, p.stock, p.sold_count, p.is_on_shelf, p.status, p.sort_no, p.created_by, p.updated_by, p.created_at, p.updated_at, p.deleted_at FROM yc_shop_product p WHERE p.deleted_at IS NULL
AND ( p.name LIKE CONCAT('%', #{keyword}, '%') OR p.product_code LIKE CONCAT('%', #{keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{keyword}, '%') )
AND p.status = #{status}
AND p.is_on_shelf = #{isOnShelf}
ORDER BY p.sort_no DESC, p.updated_at DESC, p.id DESC

