mapper.select:
SELECT COUNT(1)
FROM yc_shop_order o
WHERE o.user_id = #{userId}

SELECT COUNT(1) FROM yc_shop_order o LEFT JOIN yc_user_account u ON u.id = o.user_id WHERE 1 = 1
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_name LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_phone LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%') )
AND o.status = #{status}

SELECT o.id, o.order_no, o.user_id, u.username, u.display_name, o.total_amount, o.total_quantity, o.status, o.receiver_name, o.receiver_phone, o.receiver_address, o.buyer_remark, o.payment_marked_at, o.payment_reviewed_at, o.payment_review_by, rv.display_name AS payment_review_by_name, o.payment_review_remark, o.shipped_at, o.shipped_by, sv.display_name AS shipped_by_name, o.shipping_company, o.tracking_no, o.created_at, o.updated_at FROM yc_shop_order o LEFT JOIN yc_user_account u ON u.id = o.user_id LEFT JOIN yc_user_account rv ON rv.id = o.payment_review_by LEFT JOIN yc_user_account sv ON sv.id = o.shipped_by WHERE 1 = 1
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_name LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_phone LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%') )
AND o.status = #{status}
ORDER BY o.created_at DESC, o.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT DISTINCT p.id, p.product_code, p.name, p.subtitle, p.cover_url, p.detail_content, p.price, p.stock, p.sold_count, p.is_on_shelf, p.status, p.sort_no, p.created_by, p.updated_by, p.created_at, p.updated_at, p.deleted_at FROM yc_shop_order o INNER JOIN yc_shop_order_item oi ON oi.order_id = o.id INNER JOIN yc_shop_product p ON p.id = oi.product_id WHERE o.user_id = #{userId} AND o.status IN
#{status}
AND p.deleted_at IS NULL ORDER BY p.updated_at DESC, p.id DESC

